 * Handles both forms so callers can use either style.
 */
function flag(argv: string[], name: string): string | undefined {
  // --name=value form
  const prefix = `--${name}=`;
  const eqMatch = argv.find((a) => a.startsWith(prefix));
  if (eqMatch) return eqMatch.slice(prefix.length);
