      'case "$1" in',
      '  -V) echo "tmux 3.4 (fake)"; exit 0;;',
      `  list-windows) printf '${windowList}\\n'; exit 0;;`,
      "  *) exit 0;;",
      "esac",
      "",
    ].join("\n"),
    { mode: 0o755 }
  );
  return binDir;
}

