      if (parsed === null || typeof parsed !== "object") continue;
      const obj = parsed as <HIGH_ENTROPY_REDACTED>;
      const name = obj.event_name ?? obj.event;
      if (name === "run_started" || name === "run_closed") {
        out.push(obj);
